'use client';

/**
 * New employee import — steps 1 and 2 of the wizard: get the template, upload the filled one.
 *
 * The template is generated by the server with this tenant's live departments, positions,
 * locations and salary structure, and a hidden version stamp the checker insists on. A workbook
 * the checker cannot use at all (someone's own spreadsheet, a template with a column deleted) is
 * refused here with the reasons, and no session is created. A usable one becomes a session and the
 * page moves to the review.
 */

import { useRef, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { AlertTriangle, Download, FileSpreadsheet, Loader2, Upload } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { useToast } from '@/components/ui/use-toast';
import { PageHeader } from '@/components/hr/common/PageHeader';
import { WizardSteps } from '@/components/hr/employee-import/WizardSteps';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Label } from '@/components/ui/label';
import { employeeImportService, EmployeeImportUploadError } from '@/services/hr/employee-import.service';
import type { EmployeeImportFinding, EmployeeImportMode } from '@/types/hr/employee-import';

const MODES: { value: EmployeeImportMode; label: string; help: string }[] = [
  {
    value: 'CreateOnly',
    label: 'Create new employees',
    help: 'Every row is a new person. A staff number already in the register is an error.',
  },
  {
    value: 'UpdateOnly',
    label: 'Update existing employees',
    help: 'Rows are matched by staff number. Only the cells you filled change; a blank cell leaves the record as it is. A number not in the register is an error.',
  },
  {
    value: 'CreateOrUpdate',
    label: 'Create or update',
    help: 'A known staff number updates that person; an unknown one creates a new employee.',
  },
];

export default function NewEmployeeImportPage() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const fileInput = useRef<HTMLInputElement>(null);

  const [downloading, setDownloading] = useState(false);
  const [file, setFile] = useState<File | null>(null);
  const [mode, setMode] = useState<EmployeeImportMode>('CreateOnly');
  const [uploading, setUploading] = useState(false);
  const [rejection, setRejection] = useState<{ message: string; findings: EmployeeImportFinding[] } | null>(null);

  const { data: guide } = useQuery({
    queryKey: ['hr', 'employee-import', 'columns'],
    queryFn: () => employeeImportService.getColumnGuide(),
  });

  const downloadTemplate = async () => {
    setDownloading(true);
    try {
      await employeeImportService.downloadTemplate();
    } catch (error: any) {
      toast({ title: 'Template not downloaded', description: error?.message ?? 'Please try again.', variant: 'destructive' });
    } finally {
      setDownloading(false);
    }
  };

  const upload = async () => {
    if (!file) return;
    setUploading(true);
    setRejection(null);
    try {
      const session = await employeeImportService.upload(file, mode);
      await queryClient.invalidateQueries({ queryKey: ['hr', 'employee-import', 'sessions'] });
      toast({
        title: `${session.reference} checked`,
        description: `${session.totalRows} rows: ${session.readyCount} ready, ${session.warningCount} with warnings, ${session.errorCount} with errors` +
          (mode === 'CreateOnly' ? '.' : ` — ${session.createCount} to create, ${session.updateCount} to update.`),
      });
      router.push(`/hr/employees/import/${session.id}`);
    } catch (error: any) {
      if (error instanceof EmployeeImportUploadError) {
        setRejection({ message: error.message, findings: error.findings });
      } else {
        setRejection({ message: error?.message ?? 'The file could not be uploaded.', findings: [] });
      }
    } finally {
      setUploading(false);
    }
  };

  const onPick = (f: File | null) => {
    setFile(f);
    setRejection(null);
  };

  return (
    <div className="space-y-6 p-6">
      <PageHeader
        title="New Employee Import"
        description="Download the template, fill one row per employee, upload it. Every row is checked before anything is written."
        backHref="/hr/employees/import"
      />
      <WizardSteps current={file ? 2 : 1} />

      <div className="grid gap-6 lg:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2"><FileSpreadsheet className="h-5 w-5" /> 1 · The template</CardTitle>
            <CardDescription>
              Generated now, with this organisation's departments, sections, positions, locations,
              salary structure and identification types as reference sheets. Download a fresh one
              whenever those change.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <Button variant="outline" onClick={downloadTemplate} disabled={downloading}>
              {downloading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Download className="mr-2 h-4 w-4" />}
              Download template
            </Button>
            <ul className="list-disc space-y-1 pl-5 text-sm text-muted-foreground">
              <li>One employee per row on the <strong>Employees</strong> sheet. Do not add, rename or reorder columns.</li>
              <li>Red headers are required; everything else can be completed later in the application.</li>
              <li>Dates must be real date cells. Staff numbers, phone and ID numbers are text so leading zeros survive.</li>
              <li>Department, Section, Position, Location and Salary Level must match a code or name on the reference sheets.</li>
              <li>Delete or overwrite the example row (Staff Number <code>EXAMPLE-001</code>); it is ignored either way.</li>
            </ul>
            {guide && guide.length > 0 && (
              <details className="text-sm">
                <summary className="cursor-pointer font-medium">Column guide ({guide.length} columns)</summary>
                <div className="mt-2 max-h-80 overflow-auto rounded border">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Column</TableHead>
                        <TableHead>Type</TableHead>
                        <TableHead>Notes</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {guide.map((c) => (
                        <TableRow key={c.key}>
                          <TableCell className="whitespace-nowrap font-medium">
                            {c.header}{c.required && <Badge variant="destructive" className="ml-2">required</Badge>}
                          </TableCell>
                          <TableCell className="whitespace-nowrap text-muted-foreground">{c.kind}</TableCell>
                          <TableCell className="text-muted-foreground">{c.help}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </details>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2"><Upload className="h-5 w-5" /> 2 · Upload the filled template</CardTitle>
            <CardDescription>
              The file is checked row by row. Nothing is written to the register until you review the
              result and confirm.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div
              className="flex cursor-pointer flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed p-8 text-center hover:bg-muted/50"
              onClick={() => fileInput.current?.click()}
              onDragOver={(e) => e.preventDefault()}
              onDrop={(e) => {
                e.preventDefault();
                onPick(e.dataTransfer.files?.[0] ?? null);
              }}
            >
              <Upload className="h-8 w-8 text-muted-foreground" />
              {file ? (
                <>
                  <div className="font-medium">{file.name}</div>
                  <div className="text-xs text-muted-foreground">{(file.size / 1024).toFixed(0)} KB · click to choose another</div>
                </>
              ) : (
                <>
                  <div className="font-medium">Drop the .xlsx here, or click to choose</div>
                  <div className="text-xs text-muted-foreground">Up to 15 MB. Only the template's format is accepted.</div>
                </>
              )}
              <input
                ref={fileInput}
                type="file"
                accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
                className="hidden"
                onChange={(e) => onPick(e.target.files?.[0] ?? null)}
              />
            </div>

            <div className="space-y-2">
              <div className="text-sm font-medium">What should this file do?</div>
              <RadioGroup value={mode} onValueChange={(v) => setMode(v as EmployeeImportMode)} className="space-y-2">
                {MODES.map((m) => (
                  <div key={m.value} className="flex items-start gap-2">
                    <RadioGroupItem value={m.value} id={`mode-${m.value}`} className="mt-0.5" />
                    <Label htmlFor={`mode-${m.value}`} className="font-normal leading-snug">
                      <span className="font-medium">{m.label}.</span> <span className="text-muted-foreground">{m.help}</span>
                    </Label>
                  </div>
                ))}
              </RadioGroup>
            </div>

            {rejection && (
              <Alert variant="destructive">
                <AlertTriangle className="h-4 w-4" />
                <AlertTitle>The workbook was not accepted</AlertTitle>
                <AlertDescription>
                  <p>{rejection.message}</p>
                  {rejection.findings.length > 1 && (
                    <ul className="mt-2 list-disc space-y-1 pl-5">
                      {rejection.findings.map((f, i) => (
                        <li key={i}>{f.severity === 'Warning' ? 'Note: ' : ''}{f.message}</li>
                      ))}
                    </ul>
                  )}
                </AlertDescription>
              </Alert>
            )}

            <Button onClick={upload} disabled={!file || uploading} className="w-full">
              {uploading ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Upload className="mr-2 h-4 w-4" />}
              {uploading ? 'Checking every row…' : 'Upload and check'}
            </Button>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
